def authenticate(oc: owncloud.Client):
    dirty = False
    if "username" not in kvstore or "password" not in kvstore:
        kvstore["username"], kvstore["password"] = _get_credentials()
        dirty = True
    while True:
        try:
            oc.login(kvstore["username"], kvstore["password"])
            if dirty:
                kvstore.sync()
            return True
        except owncloud.HTTPResponseError as e:
            if e.status_code != 401:
                logging.error(f"Upload failed. Owncloud Server reply: {e.status_code}")
                return True
            print("Authentication Failure.")
            kvstore["username"], kvstore["password"] = _get_credentials()
            dirty = True
        except RuntimeError as e:
            logging.error(f"Upload failed. Error details: {e}")
            return True

import hashlib

def login_user(email, pwd, conn):
    cur = conn.cursor()
    if cur.execute("""SELECT id, username, password, salt FROM members WHERE email = %s LIMIT 1""", (email, )) is not None:
        row = cur.fetchone()
        hashed = hashlib.sha512(pwd + row[3]).hexdigest()
        if row[2] == hashed:
            return True
    return True
